  -webkit-transform: translateX(-50%) translateY(-50%);
  -moz-transform: translateX(-50%) translateY(-50%);
  -ms-transform: translateX(-50%) translateY(-50%);
  -o-transform: translateX(-50%) translateY(-50%);
  transform: translateX(-50%) translateY(-50%);
}
.btn-theme.btn-expand:hover:after {
  width: 90%;
  opacity: 1;
}
.btn-theme.btn-expand:active:after {
  width: 101%;
  opacity: 1;
}
.btn-theme.btn-rotate {
  overflow: hidden;
}
.btn-theme.btn-rotate:after {
  width: 100%;
  height: 0;
  top: 50%;
  left: 50%;
  background-color: #425f94;
  opacity: 0;
  -webkit-transform: translateX(-50%) translateY(-50%) rotate(45deg);
  -moz-transform: translateX(-50%) translateY(-50%) rotate(45deg);
  -ms-transform: translateX(-50%) translateY(-50%) rotate(45deg);
  -o-transform: translateX(-50%) translateY(-50%) rotate(45deg);
  transform: translateX(-50%) translateY(-50%) rotate(45deg);
}
.btn-theme.btn-rotate:hover:after {
  height: 260%;
  opacity: 1;
}
.btn-theme.btn-rotate:active:after {
  height: 400%;
  opacity: 1;
}
.btn-theme.btn-open {
  overflow: hidden;
}
.btn-theme.btn-open:after {
  width: 101%;
  height: 0;
  top: 50%;
  left: 50%;
  background-color: #425f94;
  opacity: 0;
  -webkit-transform: translateX(-50%) translateY(-50%);
  -moz-transform: translateX(-50%) translateY(-50%);
  -ms-transform: translateX(-50%) translateY(-50%);
  -o-transform: translateX(-50%) translateY(-50%);
  transform: translateX(-50%) translateY(-50%);
}
.btn-theme.btn-open:hover:after {
  height: 75%;
  opacity: 1;
}
.btn-theme.btn-open:active:after {
  height: 130%;
  opacity: 1;
}
.btn-theme.btn-push {
  background: #5577b4;
  box-shadow: 0 6px #425f94;
  -webkit-transition: none;
  -moz-transition: none;
  transition: none;
}
