  box-shadow: 0 4px #425f94;
  top: 2px;
}
.btn-theme.btn-push:active {
  box-shadow: 0 0 #425f94;
  top: 6px;
}
.btn-theme.btn-pushright {
  background: #5577b4;
  box-shadow: 6px 0 #425f94;
  -webkit-transition: none;
  -moz-transition: none;
  transition: none;
}
