  padding: 15px 10px;
  border-bottom: 2px solid #546E7A;
  min-height: 81px;
}
.sidebar-content .media-heading {
  color: #f5f5f5;
}
.sidebar-content .media-heading span {
  color: #f5f5f5;
}
.sidebar-content small {
  color: #f5f5f5;
}
.sidebar-content .close {
  color: white;
}
.sidebar-content:after {
  position: absolute;
  content: "";
  left: 37px;
  top: 0px;
  bottom: 0px;
  z-index: -1;
}
.sidebar-content img {
  width: 54px;
  height: 54px;
}
.sidebar-content .media {
  margin-top: 0;
}
.sidebar-content .media-heading {
  font-weight: 300 !important;
  margin-bottom: 2px;
  margin-top: 5px;
}
.sidebar-content .close {
  position: absolute;
  top: -2px;
  right: 2px;
  font-size: 19px;
  font-weight: normal;
  text-shadow: 0 1px 0 #FFF;
}
.sidebar-content .btn {
  opacity: .7;
}
.sidebar-content .btn:hover {
  opacity: 1;
}

